/* Saved invoice designs use structured text/options; no executable template code. */
const templateSections=[['header','Business header'],['details','Customer & vehicle details'],['items','Services & spare parts'],['totals','Totals & payment balance'],['payment','QR & stamp'],['bank','Bank details'],['footer','Footer']];
const requiredTemplateSections=['header','details','items','totals'];
let invoiceTemplateChoices={},templateEditing=null;
function defaultTemplate(mode){return {id:'',name:'My '+(mode==='thermal'?'Thermal':'Invoice')+' Template',mode,accent:'#1d4ed8',logoSize:70,heading:'',footerNote:'',order:templateSections.map(s=>s[0]),hidden:[],layout:{...customLayout(mode),enabled:true}}}
function cleanTemplate(input){let t=structuredClone(input);t.name=String(t.name||'').trim();if(!t.name||t.name.length>80)throw Error('Enter a template name (up to 80 characters).');if(!['regular','thermal'].includes(t.mode))throw Error('Choose a supported invoice type.');if(!/^#[0-9a-f]{6}$/i.test(t.accent))throw Error('Choose a valid accent color.');if(!Number.isFinite(Number(t.logoSize))||Number(t.logoSize)<25||Number(t.logoSize)>140)throw Error('Logo size must be 25–140 px.');validateCustomLayout(t.layout,t.mode);t.order=[...new Set([...(t.order||[]),...templateSections.map(s=>s[0])])].filter(k=>templateSections.some(s=>s[0]===k));t.hidden=(t.hidden||[]).filter(k=>!requiredTemplateSections.includes(k)&&templateSections.some(s=>s[0]===k));t.heading=String(t.heading||'').slice(0,80);t.footerNote=String(t.footerNote||'').slice(0,500);return t}
function selectedTemplate(mode,key,id){let choice=invoiceTemplateChoices[mode+'|'+key+'|'+id]??db.settings.defaultInvoiceTemplates?.[mode];return (db.invoiceTemplates||[]).find(t=>t.id===choice&&t.mode===mode)||null}
function applyDesignedTemplate(sheet,template){if(!sheet)return;sheet.querySelectorAll(':scope > .templateSection').forEach(n=>{while(n.firstChild)sheet.insertBefore(n.firstChild,n);n.remove()});if(!template)return;let t=cleanTemplate(template),groups=Object.fromEntries(templateSections.map(([k])=>[k,[]])),thermal=t.mode==='thermal';let nodes=Array.from(sheet.children);for(let i=0;i<nodes.length;i++){let n=nodes[i],key='footer';if(n.matches('.taxCaption,.invoicebrand')||thermal&&i===0)key='header';else if(n.matches('.invoiceinfo,.invoiceComplaint'))key='details';else if(n.matches('h4,.tablewrap,.thermalItems'))key='items';else if(n.matches('.invoiceBottom,dl'))key='totals';else if(n.matches('.paymentStampFooter')||n.querySelector('.thermalQr,.thermalStamp')||thermal&&n.textContent.startsWith('UPI:'))key='payment';else if(n.matches('.invoiceBankDetails'))key='bank';else if(thermal&&n.matches('p')&&n.innerHTML.includes('Date:'))key='details';else if(thermal&&n.matches('hr')){n.remove();continue}groups[key].push(n)}for(let key of t.order){let section=document.createElement('section');section.className='templateSection templateSection-'+key;section.dataset.templateSection=key;if(t.hidden.includes(key))section.hidden=true;for(let node of groups[key])section.appendChild(node);if(section.childNodes.length)sheet.appendChild(section)}applyCustomLayout(sheet,t.layout,t.mode);sheet.classList.add('designedInvoice');sheet.style.setProperty('--template-accent',t.accent);for(let image of sheet.querySelectorAll('.garageLogo')){image.style.width=t.logoSize+'px';image.style.height=t.logoSize+'px'}if(t.heading){let header=sheet.querySelector('.templateSection-header'),title=document.createElement('p');title.className='templateCustomHeading';title.textContent=t.heading;header?.appendChild(title)}if(t.footerNote){let footer=sheet.querySelector('.templateSection-footer');if(!footer){footer=document.createElement('section');footer.className='templateSection templateSection-footer';sheet.appendChild(footer)}let text=document.createElement('p');text.className='templateFooterNote';text.textContent=t.footerNote;footer.appendChild(text)}}
function saveInvoiceTemplate(template,asDefault){let clean=cleanTemplate(template),before=structuredClone(db);if(!clean.id)clean.id='TPL-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);db.invoiceTemplates=db.invoiceTemplates||[];let index=db.invoiceTemplates.findIndex(t=>t.id===clean.id);if(index<0)db.invoiceTemplates.push(clean);else db.invoiceTemplates[index]=clean;if(asDefault)db.settings.defaultInvoiceTemplates={...db.settings.defaultInvoiceTemplates,[clean.mode]:clean.id};audit('Invoice Template',clean.name+' saved');if(save('Invoice template saved')===false){db=before;return null}return clean}
function templateDesignerForm(t){return `<form id="invoiceTemplateForm"><label class="field"><span>Template Name</span><input name="name" required maxlength="80" value="${esc(t.name)}"></label><div class="formgrid">${[{key:'width',label:'Paper Width (mm)'},...(t.mode==='regular'?[{key:'height',label:'Paper Height (mm)'}]:[]),{key:'margin',label:'Margin (mm)'},{key:'font',label:'Font Size (px)'},{key:'spacing',label:'Row Spacing (px)'}].map(f=>field({...f,type:'number'},t.layout)).join('')}<label class="field"><span>Accent Color</span><input type="color" name="accent" value="${t.accent}"></label>${field({key:'logoSize',label:'Logo Size (px)',type:'number'},t)}</div>${field({key:'heading',label:'Extra Header Text'},t)}${field({key:'footerNote',label:'Extra Footer Text',type:'textarea'},t)}<h4>Section Order & Visibility</h4><div id="templateSectionOrder"></div><label class="customToggle"><input type="checkbox" name="asDefault" checked> Use as default for ${t.mode==='regular'?'regular invoices':'thermal receipts'}</label><p id="templateDesignerStatus" role="status"></p><button type="submit" class="btn">Save Template</button></form>`}
function openInvoiceTemplateDesigner(mode='regular',templateId){let t=templateId?structuredClone((db.invoiceTemplates||[]).find(t=>t.id===templateId)):defaultTemplate(mode);if(!t)return;mode=t.mode;let key=db.jobs.length?'jobs':db.sales.length?'sales':null,id=key?db[key][0].id:null,html='';if(key){let overrideKey=mode+'|'+key+'|'+id,prior=invoiceTemplateChoices[overrideKey];invoiceTemplateChoices[overrideKey]='';try{if(mode==='thermal')openThermalInvoice(key,id,t.layout.width);else invoice(key,id);html=$('#modalBody '+(mode==='thermal'?'.thermalInvoice':'.invoice'))?.outerHTML||''}finally{if(prior===undefined)delete invoiceTemplateChoices[overrideKey];else invoiceTemplateChoices[overrideKey]=prior}}templateEditing=t;openModal('Invoice Template Designer — '+(mode==='thermal'?'Thermal':'Regular'),`<div class="customLayoutDesigner templateDesigner"><div class="customLayoutOptions">${templateDesignerForm(t)}</div><div class="customLayoutPreview" id="templateDesignPreview">${html||'<p>Create a job card or sale to preview a template.</p>'}</div></div><div class="formactions">${btn('Close','cancel','secondary')}</div>`);let form=$('#invoiceTemplateForm');function read(preview=false){let values=new FormData(form),next=structuredClone(t);for(let key of ['name','accent','heading','footerNote'])next[key]=String(values.get(key)||'');next.logoSize=Number(values.get('logoSize'));for(let key of ['width','height','margin','font','spacing'])if(values.has(key))next.layout[key]=Number(values.get(key));next.layout.enabled=true;next.hidden=Array.from(form.querySelectorAll('[data-template-visible]')).filter(b=>!b.checked&&!b.disabled).map(b=>b.dataset.templateVisible);return preview?templatePreviewValues(next,t):cleanTemplate(next)}function paint(){try{let next=read(true);t={...next};let host=$('#templateDesignPreview');host.innerHTML=html;if(html)applyDesignedTemplate(host.firstElementChild,t);$('#templateDesignerStatus').textContent='Live preview updated · '+new Date().toLocaleTimeString()+' · Save Template to keep this design.'}catch(err){$('#templateDesignerStatus').textContent=err.message}}function order(){let host=$('#templateSectionOrder');host.innerHTML=t.order.map((key,i)=>`<div class="templateOrderRow"><label><input type="checkbox" data-template-visible="${key}" ${!t.hidden.includes(key)?'checked':''} ${requiredTemplateSections.includes(key)?'disabled':''}> ${esc(templateSections.find(s=>s[0]===key)[1])}</label><button type="button" data-section-up="${i}" ${i===0?'disabled':''} aria-label="Move section up">↑</button><button type="button" data-section-down="${i}" ${i===t.order.length-1?'disabled':''} aria-label="Move section down">↓</button></div>`).join('');for(let b of host.querySelectorAll('[data-section-up],[data-section-down]'))b.onclick=()=>{let i=Number(b.dataset.sectionUp??b.dataset.sectionDown),j=b.hasAttribute('data-section-up')?i-1:i+1;try{t=read()}catch(err){$('#templateDesignerStatus').textContent=err.message;return}[t.order[i],t.order[j]]=[t.order[j],t.order[i]];order();paint()}}order();form.addEventListener('input',paint);form.addEventListener('change',paint);form.onsubmit=e=>{e.preventDefault();try{let saved=saveInvoiceTemplate(read(),form.querySelector('[name="asDefault"]').checked);if(saved){t=saved;$('#templateDesignerStatus').textContent='Template saved. Open an invoice to use it.'}}catch(err){$('#templateDesignerStatus').textContent=err.message}};paint()}
function addTemplateChoice(mode,key,id){let controls=$('#modalBody .invoiceFormatControls');if(!controls)return;let select=document.createElement('select');select.setAttribute('aria-label','Saved invoice template');select.innerHTML='<option value="">Standard / Custom Layout</option>'+opts((db.invoiceTemplates||[]).filter(t=>t.mode===mode).map(t=>({value:t.id,label:t.name})),selectedTemplate(mode,key,id)?.id||'');select.onchange=()=>{invoiceTemplateChoices[mode+'|'+key+'|'+id]=select.value;if(mode==='thermal')openThermalInvoice(key,id);else invoice(key,id)};controls.appendChild(select);let button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='Design Template';button.onclick=()=>openInvoiceTemplateDesigner(mode,selectedTemplate(mode,key,id)?.id);controls.appendChild(button)}
const invoiceBeforeTemplates=invoice;
invoice=function(key,id,paper){invoiceBeforeTemplates(key,id,paper);applyDesignedTemplate($('#modalBody .invoice'),selectedTemplate('regular',key,id));addTemplateChoice('regular',key,id);let t=selectedTemplate('regular',key,id);if(t)for(let button of $$('#modalBody [data-browser-print-preview],#modalBody [data-full-paper-print]'))button.onclick=()=>printCustomInvoice('regular',t.layout)};
const thermalBeforeTemplates=openThermalInvoice;
openThermalInvoice=function(key,id,width){thermalBeforeTemplates(key,id,width);applyDesignedTemplate($('#modalBody .thermalInvoice'),selectedTemplate('thermal',key,id));addTemplateChoice('thermal',key,id);let t=selectedTemplate('thermal',key,id);if(t){$('#printThermalReceipt').onclick=()=>printCustomInvoice('thermal',t.layout);let b=$('#modalBody [data-browser-print-preview]');if(b)b.onclick=()=>printCustomInvoice('thermal',t.layout)}};
const settingsBeforeTemplates=settingsPage;
settingsPage=function(){return settingsBeforeTemplates()+`<section class="panel"><div class="panelhead"><h2>Invoice Template Designer</h2></div><div class="panelbody"><p>Create named templates with your own section order, logo size, header/footer text, accent color and paper dimensions. Invoice amounts and essential billing details stay intact. Applies to regular and thermal invoices; WhatsApp images retain their existing layout.</p><div class="toolbar"><button class="btn" id="designRegularTemplate" type="button">Design Regular Invoice Template</button><button class="btn secondary" id="designThermalTemplate" type="button">Design Thermal Template</button></div>${(db.invoiceTemplates||[]).map(t=>`<div class="listoption"><span><strong>${esc(t.name)}</strong> · ${t.mode==='thermal'?'Thermal':'Regular'} · ${t.layout.width} mm</span><button class="btn secondary small" data-edit-template="${esc(t.id)}" type="button">Edit Design</button></div>`).join('')}</div></section>`};
const renderBeforeTemplates=render;
render=function(){renderBeforeTemplates();if(page!=='settings')return;if($('#designRegularTemplate'))$('#designRegularTemplate').onclick=()=>openInvoiceTemplateDesigner('regular');if($('#designThermalTemplate'))$('#designThermalTemplate').onclick=()=>openInvoiceTemplateDesigner('thermal');for(let b of $$('[data-edit-template]'))b.onclick=()=>openInvoiceTemplateDesigner('regular',b.dataset.editTemplate)};
render();
/* Keep the designer split at sidebar/browser widths; each side scrolls independently. */
const modalBeforeDesignerViewport=openModal;
openModal=function(title,html){modalBeforeDesignerViewport(title,html);let dialog=$('.dialog');if(dialog)dialog.classList.toggle('designerDialog',html.includes('customLayoutDesigner'))};
/* Preview accepts intermediate edits; saving still uses strict validation. */
function templatePreviewValues(raw,last){let next=structuredClone(raw),fallback=structuredClone(last);next.name=String(next.name||'').trim()||fallback.name||'Invoice Template';let limits={width:next.mode==='thermal'?[48,112]:[100,330],height:[140,500],margin:[0,25],font:[8,18],spacing:[2,12]};for(let [key,[min,max]]of Object.entries(limits)){let value=Number(next.layout[key]);if(!Number.isFinite(value)||value<min||value>max)next.layout[key]=fallback.layout[key]}if(next.layout.margin>next.layout.width/4)next.layout.margin=Math.min(fallback.layout.margin,next.layout.width/4);if(!Number.isFinite(Number(next.logoSize))||Number(next.logoSize)<25||Number(next.logoSize)>140)next.logoSize=fallback.logoSize;if(!/^#[0-9a-f]{6}$/i.test(next.accent))next.accent=fallback.accent;return cleanTemplate(next)}
const applyTemplateBeforeLiveSizing=applyDesignedTemplate;
applyDesignedTemplate=function(sheet,template){applyTemplateBeforeLiveSizing(sheet,template);if(!sheet||!template)return;let t=cleanTemplate(template);if(t.mode==='regular'){sheet.style.minHeight=(t.layout.height-2*t.layout.margin)+'mm';sheet.style.setProperty('--template-header-font',Math.round(t.layout.font*1.8)+'px')}sheet.dataset.livePreviewUpdated=String(Date.now())};
